package com.paytrace.payment;
import com.paytrace.ledger.*;import com.paytrace.provider.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.*;import org.springframework.test.annotation.DirtiesContext;import java.math.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:paytrace-test;MODE=PostgreSQL;DB_CLOSE_DELAY=-1") @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS) class PaymentIdempotencyIntegrationTest { @Autowired PaymentService service;@Autowired PaymentRepository payments;@Autowired PaymentEventRepository events;@Autowired ProviderPaymentRepository provider;@Autowired LedgerTransactionRepository ledger;@Test void twentyConcurrentRequestsCreateOneFinancialIntent() throws Exception {var request=new CreatePaymentRequest("checkout-89271",new BigDecimal("1000.00"),"INR");try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var calls=java.util.stream.IntStream.range(0,20).mapToObj(i->executor.submit(()->service.create(request,"checkout_89271",ProviderFaultMode.NORMAL))).toList();for(var call:calls)assertThat(call.get(10,TimeUnit.SECONDS).paymentId()).isNotNull();}var p=payments.findByIdempotencyKey("checkout_89271").orElseThrow();assertThat(provider.findByPaymentId(p.id()).orElseThrow().captureCount()).isEqualTo(1);assertThat(ledger.findByPaymentId(p.id())).hasSize(1);assertThat(events.countByPaymentIdAndEventType(p.id(),PaymentEventType.IDEMPOTENCY_HIT)).isEqualTo(19);}@Test void rejectsDifferentPayloadOnReusedKey(){service.create(new CreatePaymentRequest("r",new BigDecimal("1.00"),"INR"),"same-key",ProviderFaultMode.NORMAL);assertThatThrownBy(()->service.create(new CreatePaymentRequest("r",new BigDecimal("2.00"),"INR"),"same-key",ProviderFaultMode.NORMAL)).isInstanceOf(PaymentService.IdempotencyConflictException.class);}}
